"""Validate published documentation examples without executing them."""

from __future__ import annotations

import ast
import json
import os
import re
import shutil
import subprocess
import sys
import textwrap
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]

GENERATED_MARKER = (
    "<!-- Generated by generate_sdk_reference.py. Do not edit. -->"
)

# Use the same registry and Markdown parser as validate-docs.mjs.
EXTRACT_EXAMPLES = r"""
import { unified } from 'unified';
import remarkParse from 'remark-parse';
import { loadDocs } from './scripts/docs-source.mjs';

const parser = unified().use(remarkParse);
const { pages } = loadDocs();
const examples = [];

function walk(node, page) {
    if (node.type === 'code' && node.lang) {
        examples.push({
            path: page.path,
            slug: page.slug,
            language: node.lang.toLowerCase(),
            meta: node.meta || '',
            code: node.value,
            line: node.position?.start.line || 1,
            generated: page.raw.includes(
                '<!-- Generated by generate_sdk_reference.py. Do not edit. -->'
            ),
        });
    }

    node.children?.forEach(child => walk(child, page));
}

for (const page of Object.values(pages)) {
    walk(parser.parse(page.raw), page);
}

console.log(JSON.stringify(examples));
"""


def load_examples() -> list[dict]:
    result = subprocess.run(
        [
            "node",
            "--input-type=module",
            "-e",
            EXTRACT_EXAMPLES,
        ],
        cwd=ROOT,
        capture_output=True,
        encoding="utf-8",
        check=True,
        timeout=60,
    )

    return json.loads(result.stdout)


def find_bash() -> str | None:
    """Prefer Git Bash on Windows over the WSL launcher."""

    if os.name == "nt":
        roots = (
            os.environ.get("ProgramFiles"),
            os.environ.get("ProgramW6432"),
            os.environ.get("ProgramFiles(x86)"),
            os.environ.get("LOCALAPPDATA"),
        )

        for root in filter(None, roots):
            candidates = (
                Path(root) / "Git" / "bin" / "bash.exe",
                Path(root) / "Programs" / "Git" / "bin" / "bash.exe",
            )

            for candidate in candidates:
                if candidate.is_file():
                    return str(candidate)

        git = shutil.which("git")

        if git:
            candidate = (
                Path(git).resolve().parent.parent
                / "bin"
                / "bash.exe"
            )

            if candidate.is_file():
                return str(candidate)

    return shutil.which("bash")


def is_signature(example: dict, code: str) -> bool:
    """Recognise generated or explicitly labelled API signatures."""

    metadata = example["meta"].split()

    if "kind=signature" in metadata:
        return True

    return (
        example["generated"]
        and re.match(
            r"^(?:(?:async\s+)?def\s+|Entity\s*\()",
            code,
        )
        is not None
    )


def validate_signature(code: str) -> None:
    """Validate a declaration using a synthetic function body."""

    if re.match(r"^Entity\s*\(", code):
        code = f"def {code}"

    if not re.match(r"^(?:async\s+)?def\s+", code):
        raise SyntaxError("Expected a Python function signature")

    if not code.rstrip().endswith(":"):
        code += ":"

    ast.parse(f"{code}\n    pass\n")


def validate_python(example: dict) -> str:
    code = textwrap.dedent(example["code"]).strip()

    if not code:
        raise SyntaxError("Empty Python example")

    if is_signature(example, code):
        validate_signature(code)
        return "signature"

    # Parsing only: no imports, credentials or code execution.
    ast.parse(code, filename=example["path"])

    return "python"


def is_curl_example(example: dict) -> bool:
    language = example["language"]

    if language == "curl":
        return True

    if language in {"bash", "sh", "shell"}:
        return bool(
            re.search(r"\bcurl(?:\.exe)?\b", example["code"])
        )

    return False


def validate_curl(example: dict, bash: str) -> None:
    """Check shell syntax, including quoting and heredocs."""

    code = example["code"]

    if not code.strip():
        raise ValueError("Empty cURL example")

    env = os.environ.copy()

    # Prevent shell startup configuration from being loaded.
    env.pop("BASH_ENV", None)
    env.pop("ENV", None)

    result = subprocess.run(
        [
            bash,
            "--noprofile",
            "--norc",
            "-n",
        ],
        input=code + "\n",
        capture_output=True,
        encoding="utf-8",
        env=env,
        cwd=ROOT,
        timeout=15,
    )

    # Some malformed heredocs produce warnings with exit code zero.
    if result.returncode != 0 or result.stderr.strip():
        raise ValueError(
            result.stderr.strip()
            or f"Bash exited with code {result.returncode}"
        )


def main() -> int:
    try:
        examples = load_examples()

    except subprocess.CalledProcessError as exc:
        print(
            "Failed to load published documentation:\n"
            f"{exc.stderr}",
            file=sys.stderr,
        )
        return 1

    except (OSError, ValueError, subprocess.TimeoutExpired) as exc:
        print(f"Failed to load examples: {exc}", file=sys.stderr)
        return 1

    bash = find_bash()

    counts = {
        "python": 0,
        "signature": 0,
        "curl": 0,
        "ignored": 0,
    }

    failures: list[str] = []

    if any(is_curl_example(example) for example in examples):
        if bash is None:
            print(
                "Bash is required for cURL syntax validation. "
                "On Windows, install Git for Windows.",
                file=sys.stderr,
            )
            return 1

    for example in examples:
        location = f"{example['path']}:{example['line']}"
        language = example["language"]

        try:
            if language in {"python", "py", "python3"}:
                kind = validate_python(example)
                counts[kind] += 1

            elif is_curl_example(example):
                validate_curl(example, bash)
                counts["curl"] += 1

            else:
                counts["ignored"] += 1

        except SyntaxError as exc:
            line = example["line"] + (exc.lineno or 1)

            failures.append(
                f"{example['path']}:{line}: {exc.msg}"
            )

        except (
            ValueError,
            OSError,
            subprocess.TimeoutExpired,
        ) as exc:
            failures.append(f"{location}: {exc}")

    print()
    print("Project David documentation example validation")
    print("-" * 50)

    print(f"Python examples:       {counts['python']}")
    print(f"Reference signatures:  {counts['signature']}")
    print(f"cURL/shell examples:   {counts['curl']}")
    print(f"Other code blocks:     {counts['ignored']}")
    print(f"Failures:              {len(failures)}")

    if failures:
        print("\nValidation failures:\n")

        for failure in failures:
            print(f"  - {failure}")

        return 1

    checked = (
        counts["python"]
        + counts["signature"]
        + counts["curl"]
    )

    if checked == 0:
        print("\nNo examples found. Validation failed.")
        return 1

    print(f"\nPASS: {checked} examples and signatures validated.")

    return 0


if __name__ == "__main__":
    raise SystemExit(main())